<script setup>
import { ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAdminSession } from '@/composables/useAdminSession.js'
const email = ref(''); const password = ref(''); const loading = ref(false); const error = ref(''); const router = useRouter(); const route = useRoute(); const session = useAdminSession()
async function submit() { error.value = ''; loading.value = true; try { await session.login({ email: email.value, password: password.value }); const target = typeof route.query.redirect === 'string' && route.query.redirect.startsWith('/admin') ? route.query.redirect : '/admin'; router.replace(target) } catch (e) { error.value = e.message || 'Unable to sign in' } finally { loading.value = false } }
</script>
<template><main class="grid min-h-screen place-items-center bg-[radial-gradient(ellipse_at_top,#132132,#07090D)] p-5"><div class="w-full max-w-[440px] rounded-[28px] border border-white/10 bg-white p-7 shadow-2xl sm:p-10"><div class="mb-10 flex items-center gap-2"><img src="/assets/img/logo-white.svg" class="h-10 rounded-lg bg-[#17A6E3] p-1" alt="Raldin Casidar" /><div><p class="font-bricolage text-xl font-bold">Raldin.</p><p class="text-[10px] uppercase tracking-[.25em] text-gray-400">Studio admin</p></div></div><h1 class="font-bricolage text-4xl font-bold text-[#07090D]">Welcome back.</h1><p class="mt-2 text-gray-500">Sign in to manage your work and Apps Lab.</p><form class="mt-8 space-y-5" @submit.prevent="submit"><label class="block text-sm font-medium">Email<input v-model="email" type="email" autocomplete="username" required class="admin-input mt-2" placeholder="admin@example.com" /></label><label class="block text-sm font-medium">Password<input v-model="password" type="password" autocomplete="current-password" required class="admin-input mt-2" placeholder="Your password" /></label><p v-if="error" class="rounded-xl bg-red-50 p-3 text-sm text-red-600">{{ error }}</p><button class="admin-button-primary w-full" :disabled="loading">{{ loading ? 'Signing in…' : 'Sign in' }}</button></form><router-link to="/" class="mt-7 block text-center text-sm text-gray-400 hover:text-[#17A6E3]">← Back to public site</router-link></div></main></template>
